/**
 * Hook de listagem de funcionários (employees) com filtros.
 *
 * Faz join com cargos, lojas e contrato ativo (para mostrar prazo de experiência).
 */

import { useCallback, useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from '@/shared/hooks/use-toast';
import { isBirthdayInMonth } from '@/shared/lib/birthday';
import type { EmployeeFilters, EmployeeListItem, Contrato } from '../types';
import { proximoFimContrato } from '../lib/probation';

interface RawEmployeeRow {
  id: string;
  matricula: string;
  user_id: string | null;
  manager_id: string | null;
  loja_id: number;
  cargo_id: string;
  nome_completo: string;
  nome_social: string | null;
  cpf: string;
  rg: string | null;
  data_nascimento: string;
  genero: 'M' | 'F' | 'NB' | 'prefiro_nao_informar' | null;
  estado_civil: string | null;
  nacionalidade: string | null;
  email_corporativo: string | null;
  email_pessoal: string | null;
  telefone_celular: string | null;
  telefone_emergencia: string | null;
  contato_emergencia_nome: string | null;
  endereco_cep: string | null;
  endereco_logradouro: string | null;
  endereco_numero: string | null;
  endereco_complemento: string | null;
  endereco_bairro: string | null;
  endereco_cidade: string | null;
  endereco_uf: string | null;
  salario_base: number | null;
  conta_bancaria: Record<string, unknown> | null;
  regime: string;
  status: string;
  data_admissao: string;
  data_demissao: string | null;
  motivo_demissao: string | null;
  divulgar_aniversario: string;
  mostrar_ano_nascimento: boolean;
  data_descarte_planejada: string | null;
  foto_url: string | null;
  created_at: string;
  updated_at: string;
  deleted_at: string | null;
  cargos?: { nome: string; area: string } | null;
  lojas?: { nome: string } | null;
  contratos?: Contrato[] | null;
}

export function useEmployees(filters: EmployeeFilters = {}) {
  const [employees, setEmployees] = useState<EmployeeListItem[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchEmployees = useCallback(async () => {
    setLoading(true);
    try {
      let query = supabase
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .from('employees' as any)
        .select(
          `
            *,
            cargos:cargo_id(nome, area),
            lojas:loja_id(nome),
            contratos!inner(*)
          `,
        )
        .is('deleted_at', null)
        .eq('contratos.ativo', true);

      if (filters.loja_id != null) {
        query = query.eq('loja_id', filters.loja_id);
      }
      if (filters.cargo_id) {
        query = query.eq('cargo_id', filters.cargo_id);
      }
      if (filters.status) {
        query = query.eq('status', filters.status);
      }
      if (filters.apenas_em_experiencia) {
        query = query.eq('status', 'probation');
      }
      if (filters.search) {
        query = query.or(
          `nome_completo.ilike.%${filters.search}%,matricula.ilike.%${filters.search}%`,
        );
      }
      if (filters.aniversariantes_mes != null) {
        // PG: extract month from date
        // Filtragem direta via SQL — usamos rpc se necessário; no client filtramos depois.
      }

      query = query.order('nome_completo', { ascending: true });

      const { data, error } = await query;
      if (error) throw error;

      const rows = (data ?? []) as unknown as RawEmployeeRow[];
      let mapped: EmployeeListItem[] = rows.map((row) => {
        const contratoAtivo = row.contratos?.find((c) => c.ativo) ?? row.contratos?.[0] ?? null;
        return {
          ...row,
          regime: row.regime as EmployeeListItem['regime'],
          status: row.status as EmployeeListItem['status'],
          divulgar_aniversario: row.divulgar_aniversario as EmployeeListItem['divulgar_aniversario'],
          cargo_nome: row.cargos?.nome ?? null,
          cargo_area: (row.cargos?.area as EmployeeListItem['cargo_area']) ?? null,
          loja_nome: row.lojas?.nome ?? null,
          contrato_tipo: contratoAtivo?.tipo ?? null,
          contrato_data_fim: contratoAtivo ? proximoFimContrato(contratoAtivo) : null,
          prorrogacao_count: contratoAtivo?.prorrogacao_count ?? null,
        };
      });

      if (filters.aniversariantes_mes != null) {
        mapped = mapped.filter((e) => isBirthdayInMonth(e.data_nascimento, filters.aniversariantes_mes!));
      }

      setEmployees(mapped);
    } catch (err) {
      // eslint-disable-next-line no-console
      console.error('[useEmployees] fetch error', err);
      toast({
        title: 'Erro',
        description: 'Não foi possível carregar a lista de funcionários.',
        variant: 'destructive',
      });
      setEmployees([]);
    } finally {
      setLoading(false);
    }
  }, [
    filters.loja_id,
    filters.cargo_id,
    filters.status,
    filters.search,
    filters.apenas_em_experiencia,
    filters.aniversariantes_mes,
  ]);

  useEffect(() => {
    fetchEmployees();
  }, [fetchEmployees]);

  return { employees, loading, fetchEmployees };
}

