/**
 * Hook de notificações master — solicitações que precisam aprovação/atenção do CTO.
 */

import { useCallback, useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import type { NotificacaoMaster } from '../types';

export function useNotificacoesMaster() {
  const [items, setItems] = useState<NotificacaoMaster[]>([]);
  const [loading, setLoading] = useState(true);
  const [unreadCount, setUnreadCount] = useState(0);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .from('notificacoes_master' as any)
        .select('*')
        .order('created_at', { ascending: false })
        .limit(100);
      if (error) throw error;
      const mapped = (data ?? []) as unknown as NotificacaoMaster[];
      setItems(mapped);
      setUnreadCount(mapped.filter((n) => !n.lida).length);
    } catch {
      setItems([]);
      setUnreadCount(0);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const marcarLida = useCallback(
    async (id: string): Promise<void> => {
      try {
        await supabase
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .from('notificacoes_master' as any)
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .update({ lida: true, lida_em: new Date().toISOString() } as any)
          .eq('id', id);
        await fetchData();
      } catch {
        // ignore
      }
    },
    [fetchData],
  );

  const marcarTodasLidas = useCallback(async (): Promise<void> => {
    try {
      await supabase
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .from('notificacoes_master' as any)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .update({ lida: true, lida_em: new Date().toISOString() } as any)
        .eq('lida', false);
      await fetchData();
    } catch {
      // ignore
    }
  }, [fetchData]);

  return { items, unreadCount, loading, fetchData, marcarLida, marcarTodasLidas };
}

