import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { startOfDay, subDays, format } from 'date-fns';

const sb = supabase as any;

export function useAdminOverview() {
  const today = startOfDay(new Date()).toISOString();
  const yesterday = startOfDay(subDays(new Date(), 1)).toISOString();
  const sevenDaysAgo = subDays(new Date(), 7).toISOString();
  const thirtyDaysAgo = subDays(new Date(), 30).toISOString();

  const onlineNow = useQuery({
    queryKey: ['admin', 'online-count'],
    queryFn: async () => {
      const twoMinAgo = new Date(Date.now() - 2 * 60 * 1000).toISOString();
      const { count } = await sb
        .from('user_sessions')
        .select('*', { count: 'exact', head: true })
        .eq('is_online', true)
        .gte('last_activity', twoMinAgo);
      return count ?? 0;
    },
    refetchInterval: 15_000,
  });

  const pageViewsToday = useQuery({
    queryKey: ['admin', 'pageviews-today'],
    queryFn: async () => {
      const { count: todayCount } = await sb
        .from('user_activity_log')
        .select('*', { count: 'exact', head: true })
        .eq('event_type', 'page_view')
        .gte('created_at', today);

      const { count: yesterdayCount } = await sb
        .from('user_activity_log')
        .select('*', { count: 'exact', head: true })
        .eq('event_type', 'page_view')
        .gte('created_at', yesterday)
        .lt('created_at', today);

      return { today: todayCount ?? 0, yesterday: yesterdayCount ?? 0 };
    },
    refetchInterval: 30_000,
  });

  const avgSession = useQuery({
    queryKey: ['admin', 'avg-session'],
    queryFn: async () => {
      const { data } = await sb
        .from('user_sessions')
        .select('started_at, last_activity, ended_at')
        .gte('started_at', today);

      if (!data || data.length === 0) return 0;

      const durations = data.map((s: any) => {
        const end = s.ended_at || s.last_activity;
        return (new Date(end).getTime() - new Date(s.started_at).getTime()) / 60000;
      });
      return Math.round(durations.reduce((a: number, b: number) => a + b, 0) / durations.length);
    },
    refetchInterval: 60_000,
  });

  const errorsToday = useQuery({
    queryKey: ['admin', 'errors-today'],
    queryFn: async () => {
      const { count } = await sb
        .from('user_activity_log')
        .select('*', { count: 'exact', head: true })
        .eq('event_type', 'error')
        .gte('created_at', today);
      return count ?? 0;
    },
    refetchInterval: 30_000,
  });

  const hourlyPageViews = useQuery({
    queryKey: ['admin', 'hourly-pageviews'],
    queryFn: async () => {
      const { data } = await sb
        .from('user_activity_log')
        .select('created_at')
        .eq('event_type', 'page_view')
        .gte('created_at', today)
        .order('created_at', { ascending: true });

      const hours = Array.from({ length: 24 }, (_, i) => ({ hour: i, count: 0 }));
      (data || []).forEach((row: any) => {
        const h = new Date(row.created_at).getHours();
        hours[h].count++;
      });
      return hours;
    },
    refetchInterval: 60_000,
  });

  const topPages = useQuery({
    queryKey: ['admin', 'top-pages'],
    queryFn: async () => {
      const { data } = await sb
        .from('user_activity_log')
        .select('page_route')
        .eq('event_type', 'page_view')
        .gte('created_at', sevenDaysAgo);

      const routeCounts: Record<string, number> = {};
      (data || []).forEach((row: any) => {
        if (row.page_route) {
          routeCounts[row.page_route] = (routeCounts[row.page_route] || 0) + 1;
        }
      });
      return Object.entries(routeCounts)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 10)
        .map(([route, count]) => ({ route, count }));
    },
  });

  const dailyActiveUsers = useQuery({
    queryKey: ['admin', 'daily-active-users'],
    queryFn: async () => {
      const { data } = await sb
        .from('user_sessions')
        .select('user_id, started_at')
        .gte('started_at', thirtyDaysAgo);

      const dayMap: Record<string, Set<string>> = {};
      (data || []).forEach((row: any) => {
        const day = format(new Date(row.started_at), 'yyyy-MM-dd');
        if (!dayMap[day]) dayMap[day] = new Set();
        dayMap[day].add(row.user_id);
      });

      return Object.entries(dayMap)
        .map(([date, users]) => ({ date, count: users.size }))
        .sort((a, b) => a.date.localeCompare(b.date));
    },
  });

  const deviceDistribution = useQuery({
    queryKey: ['admin', 'device-distribution'],
    queryFn: async () => {
      const { data } = await sb
        .from('user_sessions')
        .select('device_type')
        .gte('started_at', sevenDaysAgo);

      const counts: Record<string, number> = {};
      (data || []).forEach((row: any) => {
        const dt = row.device_type || 'unknown';
        counts[dt] = (counts[dt] || 0) + 1;
      });
      return Object.entries(counts).map(([name, value]) => ({ name, value }));
    },
  });

  return {
    onlineNow,
    pageViewsToday,
    avgSession,
    errorsToday,
    hourlyPageViews,
    topPages,
    dailyActiveUsers,
    deviceDistribution,
  };
}

