import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';

const sb = supabase as any;

export interface AdminUser {
  user_id: string;
  nome: string;
  username: string;
  ativo: boolean;
  role_id: number | null;
  role_name: string | null;
  role_display_name: string | null;
  sessionCount: number;
  lastSession: string | null;
  pageViews: number;
  totalMinutes: number;
  isOnline: boolean;
}

export interface UserDetail {
  recentSessions: any[];
  recentActivity: any[];
  topPages: { route: string; count: number }[];
}

export function useAdminUsers() {
  const users = useQuery({
    queryKey: ['admin', 'users-list'],
    queryFn: async () => {
      const { data: profiles } = await supabase
        .from('profiles')
        .select('user_id, nome, username, ativo, role_id, user_roles(name, display_name)')
        .eq('ativo', true)
        .order('nome');

      // Session stats per user
      const { data: sessions } = await sb
        .from('user_sessions')
        .select('user_id, started_at, last_activity, ended_at, is_online');

      // Activity stats per user
      const { data: activity } = await sb
        .from('user_activity_log')
        .select('user_id, event_type')
        .eq('event_type', 'page_view');

      return (profiles || []).map((p: any) => {
        const userSessions = (sessions || []).filter((s: any) => s.user_id === p.user_id);
        const userActivity = (activity || []).filter((a: any) => a.user_id === p.user_id);
        const isOnline = userSessions.some(
          (s: any) =>
            s.is_online && new Date(s.last_activity).getTime() > Date.now() - 2 * 60 * 1000
        );

        const totalMinutes = userSessions.reduce((sum: number, s: any) => {
          const end = s.ended_at || s.last_activity;
          return sum + (new Date(end).getTime() - new Date(s.started_at).getTime()) / 60000;
        }, 0);

        const role = p.user_roles as { name: string; display_name: string } | null;

        return {
          user_id: p.user_id,
          nome: p.nome,
          username: p.username,
          ativo: p.ativo,
          role_id: p.role_id,
          role_name: role?.name || null,
          role_display_name: role?.display_name || null,
          sessionCount: userSessions.length,
          lastSession:
            userSessions.length > 0
              ? userSessions.sort(
                  (a: any, b: any) =>
                    new Date(b.started_at).getTime() - new Date(a.started_at).getTime()
                )[0].started_at
              : null,
          pageViews: userActivity.length,
          totalMinutes: Math.round(totalMinutes),
          isOnline,
        } as AdminUser;
      });
    },
  });

  const getUserDetail = async (userId: string): Promise<UserDetail> => {
    const [sessionsRes, activityRes] = await Promise.all([
      sb
        .from('user_sessions')
        .select('*')
        .eq('user_id', userId)
        .order('started_at', { ascending: false })
        .limit(10),
      sb
        .from('user_activity_log')
        .select('page_route, event_type, created_at, element_id, metadata')
        .eq('user_id', userId)
        .order('created_at', { ascending: false })
        .limit(100),
    ]);

    const recentActivity = activityRes.data || [];

    // Compute top pages from activity
    const routeCounts: Record<string, number> = {};
    recentActivity.forEach((a: any) => {
      if (a.event_type === 'page_view' && a.page_route) {
        routeCounts[a.page_route] = (routeCounts[a.page_route] || 0) + 1;
      }
    });
    const topPages = Object.entries(routeCounts)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 5)
      .map(([route, count]) => ({ route, count }));

    return {
      recentSessions: sessionsRes.data || [],
      recentActivity,
      topPages,
    };
  };

  return { users, getUserDetail };
}

