/**
 * @module features/pronta-entrega/model/useExpositoraMutations
 *
 * Mutations da expositora via RPCs atômicos do banco:
 * - `mover_para_expositora` — dá baixa na câmara (estoque) e credita a vitrine;
 * - `ajustar_expositora` — ajusta só a vitrine (delta ou recontagem absoluta).
 *
 * Respostas `{ok:false, erro}` viram erro (toast destrutivo); `alertas[]` do
 * retorno são exibidos como toasts de aviso. Toasts de sucesso ficam a cargo
 * de quem chama (pra fluxos em lote não spammarem).
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { supabase } from '@/integrations/supabase/client';
import { prontaEntregaKeys } from './useProntaEntregaSaldos';
import type { AjusteMotivo } from './motivos';

export interface MoverParaExpositoraInput {
  produtoId: number;
  quantidade: number;
  observacoes?: string;
}

export interface MoverParaExpositoraResult {
  ok: boolean;
  erro?: string;
  estoque_anterior?: number;
  estoque_novo?: number;
  expositora_saldo?: number;
  alertas?: string[];
}

export interface AjustarExpositoraInput {
  produtoId: number;
  quantidade: number;
  modo: 'delta' | 'absoluto';
  motivo: AjusteMotivo;
  observacoes?: string;
}

export interface AjustarExpositoraResult {
  ok: boolean;
  erro?: string;
  saldo_anterior?: number;
  saldo?: number;
  delta?: number;
}

/**
 * Mutations da expositora pra loja selecionada. Invalida saldos + histórico
 * em caso de sucesso.
 *
 * @param lojaId - Loja alvo das operações (null desabilita na prática:
 * mutations rejeitam com erro amigável).
 */
export function useExpositoraMutations(lojaId: number | null) {
  const queryClient = useQueryClient();

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: prontaEntregaKeys.saldos(lojaId) });
    queryClient.invalidateQueries({ queryKey: prontaEntregaKeys.historico(lojaId) });
  };

  const mover = useMutation({
    mutationFn: async (input: MoverParaExpositoraInput): Promise<MoverParaExpositoraResult> => {
      if (lojaId === null) throw new Error('Nenhuma loja selecionada.');
      const { data, error } = await supabase.rpc('mover_para_expositora', {
        p_produto_master_id: input.produtoId,
        p_loja_id: lojaId,
        p_quantidade: input.quantidade,
        p_observacoes: input.observacoes,
      });
      if (error) throw new Error(error.message);
      const result = data as unknown as MoverParaExpositoraResult;
      if (!result?.ok) {
        throw new Error(result?.erro ?? 'Erro ao mover produto para a expositora.');
      }
      return result;
    },
    onSuccess: (result) => {
      invalidate();
      for (const alerta of result.alertas ?? []) {
        toast.warning(alerta);
      }
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });

  const ajustar = useMutation({
    mutationFn: async (input: AjustarExpositoraInput): Promise<AjustarExpositoraResult> => {
      if (lojaId === null) throw new Error('Nenhuma loja selecionada.');
      const { data, error } = await supabase.rpc('ajustar_expositora', {
        p_produto_master_id: input.produtoId,
        p_loja_id: lojaId,
        p_quantidade: input.quantidade,
        p_modo: input.modo,
        p_motivo: input.motivo,
        p_observacoes: input.observacoes,
      });
      if (error) throw new Error(error.message);
      const result = data as unknown as AjustarExpositoraResult;
      if (!result?.ok) {
        throw new Error(result?.erro ?? 'Erro ao ajustar a expositora.');
      }
      return result;
    },
    onSuccess: () => {
      invalidate();
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });

  return { mover, ajustar };
}

