/**
 * Sininho de notificações master no header.
 * - Subscribe Realtime na tabela notificacoes_master
 * - Dropdown com últimas 10 não-lidas + ações inline
 * - Atualiza badge em tempo real
 */

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Bell,
  Plane,
  UserMinus,
  Gavel,
  AlertCircle,
  ClipboardCheck,
  Wind,
} from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { Button } from '@/shared/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from '@/shared/ui/dropdown-menu';
import { useIsRhMaster } from '../lib/permissions';
import type { NotificacaoMaster, NotificacaoMasterTipo } from '../types';

const TIPO_ICON: Record<NotificacaoMasterTipo, React.ComponentType<{ className?: string }>> = {
  ferias_solicitacao: Plane,
  ferias_aprovada: Plane,
  ferias_rejeitada: Plane,
  ferias_aviso_pendente_assinatura: Plane,
  desligamento_solicitado: UserMinus,
  desligamento_realizado: UserMinus,
  punitivo_cadastrado: Gavel,
  experiencia_decisao: AlertCircle,
  pesquisa_saida_preenchida: ClipboardCheck,
  pesquisa_clima_resposta: Wind,
};

const TIPO_ROUTE: Record<NotificacaoMasterTipo, string> = {
  ferias_solicitacao: '/funcionarios/ferias',
  ferias_aprovada: '/funcionarios/ferias',
  ferias_rejeitada: '/funcionarios/ferias',
  ferias_aviso_pendente_assinatura: '/funcionarios/ferias',
  desligamento_solicitado: '/funcionarios/desligamentos',
  desligamento_realizado: '/funcionarios/desligamentos',
  punitivo_cadastrado: '/funcionarios/metodos-punitivos',
  experiencia_decisao: '/funcionarios/experiencia',
  pesquisa_saida_preenchida: '/funcionarios/pesquisa-saida',
  pesquisa_clima_resposta: '/funcionarios/pesquisa-clima',
};

export function NotificationBell() {
  const navigate = useNavigate();
  const isRhMaster = useIsRhMaster();
  const [items, setItems] = useState<NotificacaoMaster[]>([]);
  const [unread, setUnread] = useState(0);

  const fetch = async () => {
    const { data } = await supabase
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .from('notificacoes_master' as any)
      .select('*')
      .order('created_at', { ascending: false })
      .limit(20);
    const arr = (data ?? []) as unknown as NotificacaoMaster[];
    setItems(arr);
    setUnread(arr.filter((n) => !n.lida).length);
  };

  useEffect(() => {
    if (!isRhMaster) return;
    fetch();

    // Realtime
    const channel = supabase
      .channel('notificacoes_master_bell')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'notificacoes_master' },
        () => fetch(),
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const marcarLida = async (id: string) => {
    await supabase
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .from('notificacoes_master' as any)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .update({ lida: true, lida_em: new Date().toISOString() } as any)
      .eq('id', id);
  };

  const marcarTodas = async () => {
    await supabase
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .from('notificacoes_master' as any)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .update({ lida: true, lida_em: new Date().toISOString() } as any)
      .eq('lida', false);
  };

  if (!isRhMaster) return null;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button data-mia-action="notifica-es"
          variant="ghost"
          size="icon"
          className="relative h-9 w-9 rounded-xl hover:bg-[#57715B]/10"
          aria-label="Notificações"
        >
          <Bell className="h-5 w-5 text-[#57715B] dark:text-[#E6DCCF]" />
          {unread > 0 && (
            <span className="absolute -top-0.5 -right-0.5 h-4 min-w-4 px-1 rounded-full bg-red-500 text-white text-[10px] font-bold flex items-center justify-center">
              {unread > 9 ? '9+' : unread}
            </span>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        className="w-80 max-h-[480px] overflow-y-auto rounded-2xl border-[#57715B]/10 bg-white/95 dark:bg-zinc-900/95 backdrop-blur-xl p-0"
      >
        <div className="flex items-center justify-between p-3 border-b border-[#57715B]/10">
          <p className="font-bold text-sm text-[#2D362E] dark:text-[#E6DCCF]">
            Notificações
            {unread > 0 && (
              <span className="ml-2 text-xs text-red-600">{unread} não lidas</span>
            )}
          </p>
          {unread > 0 && (
            <button
              onClick={marcarTodas}
              className="text-xs text-[#57715B] hover:underline"
            >
              Marcar todas
            </button>
          )}
        </div>
        {items.length === 0 ? (
          <div className="py-8 text-center text-sm text-[#8C7B6D] dark:text-[#9BA59C]">
            Sem notificações
          </div>
        ) : (
          <div className="divide-y divide-[#57715B]/5">
            {items.map((n) => {
              const Icon = TIPO_ICON[n.tipo] ?? Bell;
              return (
                <button
                  key={n.id}
                  onClick={() => {
                    if (!n.lida) marcarLida(n.id);
                    navigate(TIPO_ROUTE[n.tipo] ?? '/funcionarios');
                  }}
                  className={`w-full text-left p-3 hover:bg-[#57715B]/5 transition-colors ${
                    !n.lida ? 'bg-[#57715B]/5' : ''
                  }`}
                >
                  <div className="flex items-start gap-2">
                    <Icon className="h-4 w-4 text-[#57715B] shrink-0 mt-0.5" />
                    <div className="flex-1 min-w-0">
                      <p className={`text-sm truncate ${!n.lida ? 'font-bold' : ''} text-[#2D362E] dark:text-[#E6DCCF]`}>
                        {n.titulo}
                      </p>
                      {n.descricao && (
                        <p className="text-xs text-[#8C7B6D] dark:text-[#9BA59C] line-clamp-2 mt-0.5">
                          {n.descricao}
                        </p>
                      )}
                      <p className="text-[10px] text-[#8C7B6D]/70 mt-1 font-mono">
                        {new Date(n.created_at).toLocaleString('pt-BR')}
                      </p>
                    </div>
                    {!n.lida && (
                      <span className="h-2 w-2 rounded-full bg-red-500 mt-2 shrink-0" />
                    )}
                  </div>
                </button>
              );
            })}
          </div>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

