33	    'eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'like', 'ilike',
34	    'is', 'in', 'not', 'or', 'filter', 'match',
35	    'order', 'limit', 'range', 'single', 'maybeSingle',
