/**
 * Tipos de domínio da feature Ouvidoria.
 *
 * DenunciaOuvidoria omite senha_hash para nunca expor o hash ao client.
 * MensagemThread restringe autor a union explícita (o banco pode guardar
 * qualquer string, mas só produzimos 'denunciante' | 'ouvidoria').
 */

// ---------------------------------------------------------------------------
// Enums de domínio
// ---------------------------------------------------------------------------

export type CategoriaOuvidoria =
  | 'assedio_moral'
  | 'assedio_sexual'
  | 'fraude_financeiro'
  | 'discriminacao'
  | 'seguranca_trabalho'
  | 'conduta_etica'
  | 'sugestao'
  | 'outro';

export type StatusOuvidoria =
  | 'recebida'
  | 'em_analise'
  | 'resolvida'
  | 'arquivada';

// ---------------------------------------------------------------------------
// Entidade — painel das donas
// ---------------------------------------------------------------------------

/**
 * Linha da tabela ouvidoria_denuncias com senha_hash omitida.
 * Derivado manualmente do Row type do banco para garantir ausência do campo
 * sensível em tempo de compilação.
 */
export interface DenunciaOuvidoria {
  id: string;
  protocolo: string;
  categoria: CategoriaOuvidoria;
  loja_id: number | null;
  mensagem: string;
  status: StatusOuvidoria;
  created_at: string;
  updated_at: string;
  ultima_resposta_em: string | null;
}

// ---------------------------------------------------------------------------
// Thread de mensagens
// ---------------------------------------------------------------------------

export interface MensagemThread {
  autor: 'denunciante' | 'ouvidoria';
  mensagem: string;
  created_at: string;
}

// ---------------------------------------------------------------------------
// Resultado da consulta por protocolo (canal anônimo)
// ---------------------------------------------------------------------------

export interface ConsultaProtocoloDenuncia {
  protocolo: string;
  categoria: CategoriaOuvidoria;
  loja_id: number | null;
  mensagem: string;
  status: StatusOuvidoria;
  created_at: string;
  updated_at: string;
  ultima_resposta_em: string | null;
}

export type ConsultaProtocoloResult =
  | { ok: true; denuncia: ConsultaProtocoloDenuncia; mensagens: MensagemThread[] }
  | { ok: false };

// ---------------------------------------------------------------------------
// Inputs de formulário / mutation
// ---------------------------------------------------------------------------

export interface EnviarDenunciaInput {
  categoria: CategoriaOuvidoria;
  loja_id: number | null;
  mensagem: string;
  senha: string;
}

export interface ConsultarProtocoloInput {
  protocolo: string;
  senha: string;
}

export interface ResponderProtocoloInput {
  protocolo: string;
  senha: string;
  mensagem: string;
}

export interface ResponderOuvidoriaInput {
  denuncia_id: string;
  mensagem: string;
}

export interface AtualizarStatusInput {
  denuncia_id: string;
  status: StatusOuvidoria;
}

// ---------------------------------------------------------------------------
// Filtros do painel
// ---------------------------------------------------------------------------

export interface OuvidoriaFiltros {
  status?: StatusOuvidoria;
  categoria?: CategoriaOuvidoria;
  lojaId?: number;
}

