/**
 * Verifica se o usuário autenticado tem acesso ao painel das donas.
 *
 * Fonte de verdade: RPC `can_view_ouvidoria()` — resolução via allowlist
 * na tabela `ouvidoria_acesso`. NÃO usa isAdmin nem usePermissions.
 *
 * staleTime: 5 minutos — troca de acesso é operação manual e rara.
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';

const FIVE_MINUTES = 5 * 60 * 1_000;

export function useOuvidoriaAccess(): { canView: boolean; isLoading: boolean } {
  const { data, isLoading } = useQuery<boolean>({
    queryKey: ['ouvidoria', 'access'],
    queryFn: async () => {
      const { data: result, error } = await supabase.rpc('can_view_ouvidoria');
      if (error) throw new Error(error.message);
      return result as boolean;
    },
    staleTime: FIVE_MINUTES,
    // Padrão conservador: assume sem acesso em caso de erro ou dados ausentes
    placeholderData: false,
  });

  return {
    canView: data === true,
    isLoading,
  };
}

