/**
 * Mutation para as donas responderem uma denúncia via painel interno.
 *
 * Chama `responder_ouvidoria` (SECURITY DEFINER, gated por can_view_ouvidoria).
 * A RPC lança RAISE EXCEPTION se o usuário não tiver acesso — o erro vira
 * toast destrutivo no componente chamador.
 *
 * Invalida toda a árvore de cache ['ouvidoria'] para refletir a nova mensagem
 * no detalhe e atualizar ultima_resposta_em na lista.
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { supabase } from '@/integrations/supabase/client';
import type { ResponderOuvidoriaInput } from '../types';

interface RpcResult {
  ok: boolean;
  erro?: string;
}

export function useResponderOuvidoria() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: ResponderOuvidoriaInput): Promise<void> => {
      const { data, error } = await supabase.rpc('responder_ouvidoria', {
        p_denuncia_id: input.denuncia_id,
        p_mensagem: input.mensagem,
      });
      if (error) throw new Error(error.message);

      const result = data as unknown as RpcResult;
      if (!result?.ok) {
        throw new Error(result?.erro ?? 'Não foi possível enviar a resposta.');
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['ouvidoria'] });
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

