/**
 * Lista de denúncias para o painel das donas.
 *
 * RLS garante que apenas usuários na allowlist (ouvidoria_acesso) recebem dados.
 * Colunas explícitas — senha_hash é deliberadamente excluída da seleção.
 *
 * Filtros são opcionais; queryKey os inclui para que o React Query mantenha
 * caches independentes por combinação de filtros.
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type { DenunciaOuvidoria, OuvidoriaFiltros } from '../types';

const COLUNAS =
  'id, protocolo, categoria, loja_id, mensagem, status, created_at, updated_at, ultima_resposta_em';

export function useOuvidoriaList(filtros: OuvidoriaFiltros = {}) {
  return useQuery<DenunciaOuvidoria[]>({
    queryKey: ['ouvidoria', 'list', filtros],
    queryFn: async () => {
      let query = supabase
        .from('ouvidoria_denuncias' as any) // tabela tipada via schema gerado
        .select(COLUNAS)
        .order('created_at', { ascending: false });

      if (filtros.status) {
        query = (query as any).eq('status', filtros.status);
      }
      if (filtros.categoria) {
        query = (query as any).eq('categoria', filtros.categoria);
      }
      if (filtros.lojaId !== undefined) {
        query = (query as any).eq('loja_id', filtros.lojaId);
      }

      const { data, error } = await query;
      if (error) throw new Error(error.message);
      return (data ?? []) as unknown as DenunciaOuvidoria[];
    },
  });
}

